from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x,grid[y][x]))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    core=max(comps,key=len)
    r0=min(y for y,x,v in core); r1=max(y for y,x,v in core)
    c0=min(x for y,x,v in core); c1=max(x for y,x,v in core)
    # Include nearby detached exemplar cells (e.g. diagonal marks) around the main shape.
    pr0=max(0,r0-1); pr1=min(h-1,r1+1); pc0=max(0,c0-1); pc1=min(w-1,c1+1)
    pattern=[(y-(r0+r1)//2,x-(c0+c1)//2,grid[y][x])
             for y in range(pr0,pr1+1) for x in range(pc0,pc1+1)
             if grid[y][x]!=bg and (y,x) not in {(yy,xx) for yy,xx,v in core}]
    # Add core pixels too.
    pattern += [(y-(r0+r1)//2,x-(c0+c1)//2,v) for y,x,v in core]
    corecells={(y,x) for y,x,v in core}
    targets=[]
    for comp in comps:
        if len(comp)==1 and (comp[0][0],comp[0][1]) not in corecells:
            y,x,_=comp[0]
            if not (pr0<=y<=pr1 and pc0<=x<=pc1): targets.append((y,x))
    out=[row[:] for row in grid]
    for y,x in targets:
        for dy,dx,v in pattern:
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w: out[yy][xx]=v
    return out
